--
-- Table structure for table `movements`
--

DROP TABLE IF EXISTS `movements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movements` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `movement_date` date DEFAULT NULL,
  `bill_id` int unsigned DEFAULT NULL,
  `driver` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `car_owner` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_co` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agency` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_expense` decimal(14,2) NOT NULL DEFAULT '0.00',
  `total_receipt` decimal(14,2) NOT NULL DEFAULT '0.00',
  `total_discount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_date` (`movement_date`),
  KEY `idx_bill` (`bill_id`),
  KEY `idx_driver` (`driver`),
  CONSTRAINT `fk_mv_bill` FOREIGN KEY (`bill_id`) REFERENCES `bawalis` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

